44:         const infoEventId = current.infoEvent.getId();
45: 
46:         if (!infoEventId) {
47:             throw new Error("Got broadcast info event without Id");
48:         }
49: 
50:         if (this.current) {
51:             this.current.off(VoiceBroadcastRecordingEvent.StateChanged, this.onCurrentStateChanged);
52:         }
53: 
54:         this.current = current;
55:         this.current.on(VoiceBroadcastRecordingEvent.StateChanged, this.onCurrentStateChanged);
56:         this.recordings.set(infoEventId, current);
57:         this.emit(VoiceBroadcastRecordingsStoreEvent.CurrentChanged, current);
58:     }
